def load_data():
    if _EMBED:
        return json.loads(zlib.decompress(bytes.fromhex(_EMBED)).decode("utf-8"))
    import tc01_plan as TP
    return json.loads(json.dumps(TP.bake(TP.load_runs())))


D = load_data()
FPS, N, R = D["fps"], D["N"], D["R"]
LANE_HALF, STRIP = 1.75, 0.5          # one 3.50 m lane (Landstrasse RQ 11 lane), 0.50 m edge strips
EDGE_W = 0.25                         # edge line (Breitstrich outside the Autobahn: 0.25 m)
PAVED = LANE_HALF + STRIP             # 2.25 m either side of the lane centre
BANKETT = 1.5
CHIP_COL = {1: (1.0, 0.06, 0.03), 2: (1.0, 0.55, 0.0), 3: (0.1, 0.9, 0.15), 4: (1.0, 0.4, 0.0)}
CHIP_SCALE = {"R_top": 2.4, "C_drone": 1.6, "S_drone": 0.7}     # bigger chips in the wide shots, small in the drone

