# ------------------------------------------------------------------ the ring as a "road" for the world helpers
class Ring:
    """Duck-types world.Road for terrain(), ground_z() and flora.vegetation(): distance to the track, flat inside."""
    def __init__(self, r):
        self.r = r

    def nearest(self, x, y):
        # +30 m: the terrain's field patchwork starts right at the outer verge (no soft grass halo round the ring)
        rr = math.hypot(x, y)
        d = max(0.0, rr - self.r) + 30.0
        return math.atan2(y, x) * self.r, d, 0.55       # ground_z: base = rz - 0.8 = -0.25 near the track


RING = Ring(R + PAVED + BANKETT)


def annulus(name, r0, r1, mat, c, z0=0.0, z1=None, seg=720, u0=None):
    """Flat or sloped ring band between radii r0 and r1. UV u = lateral metres (u0 at r0), v = arc length."""
    z1 = z0 if z1 is None else z1
    verts, faces, uvs = [], [], []
    for k in range(seg + 1):
        th = 2 * math.pi * k / seg
        c_, s_ = math.cos(th), math.sin(th)
        verts += [(r0 * c_, r0 * s_, z0), (r1 * c_, r1 * s_, z1)]
        uu = (u0 if u0 is not None else r0)
        uvs += [(uu, R * th), (uu + (r1 - r0), R * th)]
        if k:
            b = 2 * (k - 1)
            faces.append((b, b + 1, b + 3, b + 2))
    return W.mesh_obj(name, verts, faces, mat, c, uvs)


def disc_mesh(name, r, mat, c, z=0.0, seg=180):
    verts = [(0.0, 0.0, z)] + [(r * math.cos(2 * math.pi * k / seg), r * math.sin(2 * math.pi * k / seg), z)
                               for k in range(seg)]
    faces = [(0, 1 + k, 1 + (k + 1) % seg) for k in range(seg)]
    return W.mesh_obj(name, verts, faces, mat, c)


# ------------------------------------------------------------------ track
Z_ROAD = 0.02


def crops_mat():
    """The infield is farmland (October): plots of about 30 m (winter wheat with tramlines, ploughed soil, stubble,
    maize stubble, fallow), drill rows 2 m apart, so the top shots have texture and scale."""
    m = bpy.data.materials.new("infield_crops")
    m.use_nodes = True
    nt = m.node_tree
    p = nt.nodes["Principled BSDF"]
    p.inputs["Roughness"].default_value = 0.92
    L = nt.links
    tc = nt.nodes.new("ShaderNodeTexCoord")
    vor = nt.nodes.new("ShaderNodeTexVoronoi")
    vor.voronoi_dimensions = "2D"
    vor.distance = "CHEBYCHEV"
    vor.inputs["Scale"].default_value = 1.0
    vor.inputs["Randomness"].default_value = 0.8
    mp = nt.nodes.new("ShaderNodeMapping")
    mp.inputs["Scale"].default_value = (1 / 34.0, 1 / 26.0, 1.0)
    mp.inputs["Rotation"].default_value = (0, 0, 0.3)
    L.new(tc.outputs["Object"], mp.inputs["Vector"])
    L.new(mp.outputs["Vector"], vor.inputs["Vector"])
    sep = nt.nodes.new("ShaderNodeSeparateColor")
    L.new(vor.outputs["Color"], sep.inputs["Color"])
    ramp = nt.nodes.new("ShaderNodeValToRGB")
    ramp.color_ramp.interpolation = "CONSTANT"
    cols = [(0.0, (0.2, 0.12, 0.06)), (0.2, (0.5, 0.42, 0.22)), (0.4, (0.13, 0.3, 0.05)), (0.6, (0.42, 0.33, 0.16)),
            (0.8, (0.18, 0.34, 0.07))]
    ramp.color_ramp.elements[0].position, ramp.color_ramp.elements[0].color = cols[0][0], (*cols[0][1], 1)
    ramp.color_ramp.elements[1].position, ramp.color_ramp.elements[1].color = cols[1][0], (*cols[1][1], 1)
    for pos, col in cols[2:]:
        ramp.color_ramp.elements.new(pos).color = (*col, 1)
    L.new(sep.outputs[0], ramp.inputs["Fac"])
    wave = nt.nodes.new("ShaderNodeTexWave")
    wave.inputs["Scale"].default_value = 0.5
    wave.inputs["Distortion"].default_value = 0.6
    L.new(tc.outputs["Object"], wave.inputs["Vector"])
    rows = nt.nodes.new("ShaderNodeMix")
    rows.data_type = "RGBA"
    rows.blend_type = "MULTIPLY"
    rows.inputs["Factor"].default_value = 0.28
    L.new(ramp.outputs["Color"], rows.inputs["A"])
    L.new(wave.outputs["Color"], rows.inputs["B"])
    nz = nt.nodes.new("ShaderNodeTexNoise")
    nz.inputs["Scale"].default_value = 0.4
    L.new(tc.outputs["Object"], nz.inputs["Vector"])
    nmix = nt.nodes.new("ShaderNodeMix")
    nmix.data_type = "RGBA"
    nmix.blend_type = "OVERLAY"
    nmix.inputs["Factor"].default_value = 0.25
    L.new(rows.outputs["Result"], nmix.inputs["A"])
    L.new(nz.outputs["Color"], nmix.inputs["B"])
    L.new(nmix.outputs["Result"], p.inputs["Base Color"])
    return m


def infield_mat():
    """Mown grass of the infield: the world.py grass with mowing stripes 6 m wide (scale for the top shots)."""
    m = W.noisy("infield_grass", (0.12, 0.27, 0.05), (0.22, 0.4, 0.09), 0.15, rough=0.9, detail=5)
    nt = m.node_tree
    p = nt.nodes["Principled BSDF"]
    src_ = p.inputs["Base Color"].links[0].from_socket
    tc = nt.nodes.new("ShaderNodeTexCoord")
    sep = nt.nodes.new("ShaderNodeSeparateXYZ")
    nt.links.new(tc.outputs["Object"], sep.inputs[0])
    mul = nt.nodes.new("ShaderNodeMath")
    mul.operation = "MULTIPLY"
    mul.inputs[1].default_value = math.pi / 6.0
    nt.links.new(sep.outputs["X"], mul.inputs[0])
    sn = nt.nodes.new("ShaderNodeMath")
    sn.operation = "SINE"
    nt.links.new(mul.outputs[0], sn.inputs[0])
    gt = nt.nodes.new("ShaderNodeMath")
    gt.operation = "GREATER_THAN"
    gt.inputs[1].default_value = 0.0
    nt.links.new(sn.outputs[0], gt.inputs[0])
    mx = nt.nodes.new("ShaderNodeMix")
    mx.data_type = "RGBA"
    mx.blend_type = "MULTIPLY"
    mx.inputs["B"].default_value = (0.82, 0.86, 0.8, 1)
    nt.links.new(gt.outputs[0], mx.inputs["Factor"])
    nt.links.new(src_, mx.inputs["A"])
    nt.links.new(mx.outputs["Result"], p.inputs["Base Color"])
    return m
# asphalt UV u: lateral metres placed so the wheel tracks of world.asphalt sit 0.94 m either side of the lane centre
annulus("track_asphalt", R - PAVED, R + PAVED, M.asph, env, Z_ROAD, u0=4.625 - PAVED)
for side in (-1, 1):
    r_line = R + side * (LANE_HALF + EDGE_W / 2)
    annulus(f"edge_line{side}", r_line - EDGE_W / 2, r_line + EDGE_W / 2, M.paint, env, Z_ROAD + 0.006)
    r_a = R + side * PAVED
    r_b = R + side * (PAVED + BANKETT)
    annulus(f"bankett{side}", min(r_a, r_b), max(r_a, r_b), M.gravel, env,
            Z_ROAD - (0.0 if side > 0 else 0.1), Z_ROAD - (0.1 if side > 0 else 0.0))
R_IN = R - PAVED - BANKETT
annulus("infield_grass", R_IN - 7.0, R_IN, infield_mat(), env, Z_ROAD - 0.1)
disc_mesh("infield_crops", R_IN - 7.0, crops_mat(), env, z=Z_ROAD - 0.11)
annulus("verge_out", R + PAVED + BANKETT, R + PAVED + BANKETT + 14.0, M.grass, env, Z_ROAD - 0.1, -0.25)
W.terrain(RING, M, env, size=3200.0, res=12.5, center=(0.0, 0.0))


def leitpfosten_left(c):
    """Zeichen 620 for the left side of the road: same 1.0 m triangular post, top slanted towards the road (local +x),
    25 cm black band, two small round white reflectors one above the other."""
    tri = [(-0.06, -0.035), (0.06, -0.035), (0.0, 0.07)]

    def top(x):
        return 0.96 - (x / 0.06) * 0.04

    root = bpy.data.collections.new("leitpfosten_left")
    c.children.link(root)

    def prism(name, z0f, z1f, mat, k=1.0):
        verts = [(x * k, y * k, z0f(x)) for x, y in tri] + [(x * k, y * k, z1f(x)) for x, y in tri]
        faces = [(2, 1, 0), (3, 4, 5), (0, 1, 4, 3), (1, 2, 5, 4), (2, 0, 3, 5)]
        return W.mesh_obj(name, verts, faces, mat, root)

    prism("lpl_body", lambda x: 0.0, top, M.white)
    prism("lpl_band", lambda x: top(x) - 0.31, lambda x: top(x) - 0.06, M.black, 1.03)
    for k, z in enumerate((0.745, 0.815)):
        verts = [(0.018 * math.cos(2 * math.pi * j / 16), -0.0375, z + 0.018 * math.sin(2 * math.pi * j / 16))
                 for j in range(16)]
        W.mesh_obj(f"lpl_refl{k}", verts, [tuple(range(16))], M.refl, root)
    return root


LP_R = W.leitpfosten(M, lib)
LP_L = leitpfosten_left(lib)
n_posts = 24                                  # 15 m apart around the ring
for k in range(n_posts):
    th = 2 * math.pi * (k + 0.5) / n_posts
    for col, rr in ((LP_R, R + PAVED + 0.5), (LP_L, R - PAVED - 0.5)):
        W.instance(col, (rr * math.cos(th), rr * math.sin(th), Z_ROAD - 0.05), rz=th, c=env)

# ------------------------------------------------------------------ surroundings
groups = flora.library(lib)
excl = []
HG, CH = W.house_library(lib, M)
rnd = random.Random(4)
for vx, vy, n_h, rad, rot0 in ((-560.0, 420.0, 34, 130.0, 0.4), (720.0, -260.0, 26, 110.0, 1.1),
                               (300.0, 900.0, 30, 120.0, 0.2)):
    kids = list(HG.children)
    for _ in range(n_h):
        aa = rnd.uniform(0, 2 * math.pi)
        rr = rad * math.sqrt(rnd.random())
        px, py = vx + math.cos(aa) * rr, vy + math.sin(aa) * rr
        W.instance(rnd.choice(kids), (px, py, W.ground_z(RING, px, py) - 0.4),
                   rz=rot0 + rnd.choice((0, math.pi / 2)) + rnd.uniform(-0.15, 0.15), c=env)
    W.instance(CH, (vx, vy, W.ground_z(RING, vx, vy) - 0.4), rz=rot0, c=env)
    excl.append((vx, vy, rad + 25))
excl.append((0.0, 0.0, R + PAVED + BANKETT + 15.0))          # no trees on the infield or the verge
flora.vegetation(RING, groups, env, -1e9, 1e9, half=1300.0, center=(0.0, 0.0), spacing=8.0, exclude=excl)
TB, _rot = W.wind_turbine(M, lib)
for k, (tx, ty) in enumerate(((-900, -700), (-760, -900), (-1050, -520), (980, 640), (1150, 420), (820, 900))):
    W.instance(TB, (tx, ty, W.ground_z(RING, tx, ty) - 1.0), rz=math.radians(200 + 4 * k), c=env)

# ------------------------------------------------------------------ cars (each with its own lamps and wheels)
cars = []
for i, fl in enumerate(D["fleet"]):
    h = jx.hero(fl["kind"], tuple(fl["color"]), f"car{i:02d}", fl["plate"], lib, traffic,
                metal=0.15 if i == D["hero"] else 0.4)
    cars.append(h)


def wheel_hubs(car):
    """Put every tyre and its rim under one hub empty at the axle centre, so the hub can spin (rotation about x)."""
    g = car["coll"].objects[car["name"]]
    tyres = [o for o in car["coll"].objects if o.type == "MESH" and o.data.materials
             and o.data.materials[0].name.startswith("car_tyre")]
    rims = [o for o in car["coll"].objects if o.type == "MESH" and o.data.materials
            and o.data.materials[0].name.startswith("car_rim")]
    hubs = []
    for t in tyres:
        c0 = t.location.copy()
        hub = bpy.data.objects.new(car["name"] + "_hub", None)
        car["coll"].objects.link(hub)
        hub.parent = g
        hub.location = c0
        hub.rotation_mode = "XYZ"
        for o in [t] + [r_ for r_ in rims if abs(r_.location.y - c0.y) < 0.2 and r_.location.x * c0.x > 0]:
            o.parent = hub
            o.matrix_parent_inverse.identity()
            o.location = o.location - c0 if o is not t else Vector((0, 0, 0))
        hubs.append(dict(obj=hub, r=max(t.dimensions.x, t.dimensions.y) / 2, front=c0.y > 0))
    return hubs


frames = list(range(1, N + 1))
cuts = set(D["cuts"])
for i, car in enumerate(cars):
    s_ = D["cars"]["s"][i]
    locs, rots = [], []
    for s in s_:
        th = s / R
        locs.append((R * math.cos(th), R * math.sin(th), Z_ROAD))
        rots.append((0.0, 0.0, th))
    stage.bake_motion(car["obj"], frames, locs, rots)
    car["track"] = locs
    for hb in wheel_hubs(car):
        spin = [(-s / hb["r"], 0.0, (math.atan(2.7 / R) if hb["front"] else 0.0)) for s in s_]
        hl = [tuple(hb["obj"].location)] * N
        stage.bake_motion(hb["obj"], frames, hl, spin)
    br = D["cars"]["brake"][i]
    pairs, last = [], None
    for f, b in zip(frames, br):
        if b != last:
            pairs.append((f, 8.0 if b else 0.8))
            last = b
    jx.key_emission(car["tail"], pairs)


# ------------------------------------------------------------------ roof speed chips
def chip_mat(name):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    p = m.node_tree.nodes["Principled BSDF"]
    p.inputs["Roughness"].default_value = 0.35
    p.inputs["Emission Strength"].default_value = 1.6
    return m


chip_mats = []
for i, car in enumerate(cars):
    m = chip_mat(f"chip{i:02d}")
    chip_mats.append(m)
    bpy.ops.mesh.primitive_uv_sphere_add(segments=24, ring_count=12, radius=0.85)
    o = W.link(bpy.context.active_object, traffic)
    o.name = f"chip{i:02d}"
    o.scale = (1.0, 1.0, 0.42)
    bpy.ops.object.shade_smooth()
    o.data.materials.append(m)
    o.visible_shadow = False
    o.parent = car["obj"]
    o.location = (0.0, 0.0, car["roof"] + 1.15)
    p = m.node_tree.nodes["Principled BSDF"]
    states = D["cars"]["chip"][i]
    last = None
    for f, st in zip(frames, states):
        k = 0.0 if st == 0 else CHIP_SCALE.get(D["shot"][f - 1], 1.0)
        if (st, k) != last:
            col = CHIP_COL.get(st, (0.5, 0.5, 0.5))
            p.inputs["Base Color"].default_value = (*col, 1)
            p.inputs["Emission Color"].default_value = (*col, 1)
            p.inputs["Base Color"].keyframe_insert("default_value", frame=f)
            p.inputs["Emission Color"].keyframe_insert("default_value", frame=f)
            o.scale = (k, k, 0.42 * k)
            o.keyframe_insert("scale", frame=f)
            last = (st, k)
    for idb in (m.node_tree, o):
        for fc in stage.fcurves(idb):
            for kp in fc.keyframe_points:
                kp.interpolation = "CONSTANT"


# ------------------------------------------------------------------ the jam band (red, on the road under the jam)
def band_material():
    m = bpy.data.materials.new("jam_band")
    m.use_nodes = True
    nt = m.node_tree
    for n_ in list(nt.nodes):
        if n_.type != "OUTPUT_MATERIAL":
            nt.nodes.remove(n_)
    L = nt.links

    def node(t, **kw):
        n_ = nt.nodes.new(t)
        for k, v in kw.items():
            setattr(n_, k, v)
        return n_

    def math_(op, a_, b_=None, c_=None):
        n_ = node("ShaderNodeMath", operation=op)
        for k, v in enumerate((a_, b_, c_)):
            if v is None:
                continue
            if isinstance(v, (int, float)):
                n_.inputs[k].default_value = v
            else:
                L.new(v, n_.inputs[k])
        return n_.outputs[0]

    tc = node("ShaderNodeTexCoord")
    sep = node("ShaderNodeSeparateXYZ")
    L.new(tc.outputs["Object"], sep.inputs[0])
    ang = math_("ARCTAN2", sep.outputs["Y"], sep.outputs["X"])
    start = node("ShaderNodeValue", label="start")
    length = node("ShaderNodeValue", label="length")
    stren = node("ShaderNodeValue", label="strength")
    start.name, length.name, stren.name = "start", "length", "strength"
    rel = math_("FLOORED_MODULO", math_("SUBTRACT", ang, start.outputs[0]), 2 * math.pi)
    soft = 2.5 / R
    m_in = math_("MINIMUM", math_("DIVIDE", rel, soft), 1.0)
    m_out = math_("MINIMUM", math_("DIVIDE", math_("SUBTRACT", length.outputs[0], rel), soft), 1.0)
    mask = math_("MAXIMUM", math_("MINIMUM", m_in, m_out), 0.0)
    alpha = math_("MULTIPLY", math_("MULTIPLY", mask, stren.outputs[0]), 0.72)
    em = node("ShaderNodeEmission")
    em.inputs["Color"].default_value = (1.0, 0.07, 0.03, 1)
    em.inputs["Strength"].default_value = 3.4
    tr = node("ShaderNodeBsdfTransparent")
    mx = node("ShaderNodeMixShader")
    L.new(alpha, mx.inputs[0])
    L.new(tr.outputs[0], mx.inputs[1])
    L.new(em.outputs[0], mx.inputs[2])
    L.new(mx.outputs[0], nt.nodes["Material Output"].inputs["Surface"])
    return m, start, length, stren


band_m, b_start, b_len, b_str = band_material()
band = annulus("jam_band_mesh", R - 2.6, R + 2.6, band_m, env, Z_ROAD + 0.03)
band.visible_shadow = False
prev_strength = None
for f, (st, ln, strength) in zip(frames, D["band"]):
    b_start.outputs[0].default_value = st
    b_len.outputs[0].default_value = ln
    b_start.outputs[0].keyframe_insert("default_value", frame=f)
    b_len.outputs[0].keyframe_insert("default_value", frame=f)
    if strength != prev_strength:
        b_str.outputs[0].default_value = strength
        b_str.outputs[0].keyframe_insert("default_value", frame=f)
        prev_strength = strength
for fc in stage.fcurves(band_m.node_tree):
    if "strength" in fc.data_path:
        for kp in fc.keyframe_points:
            kp.interpolation = "CONSTANT"

# ------------------------------------------------------------------ arrows: cars forwards, the jam backwards
arrow_r = W.principled("trackc_arrow_red", (1.0, 0.08, 0.03), 0.5, emit=(1.0, 0.07, 0.03), estr=2.2)
arrow_w = W.principled("trackc_arrow_white", (0.95, 0.95, 0.95), 0.5, emit=(1.0, 1.0, 1.0), estr=1.4)
arrow_k = W.principled("trackc_arrow_line", (0.0, 0.0, 0.0), 0.6)


def arrow(name, scale=1.0, fill=None):
    arrow_y = fill
    pts = [(-1.6, -0.35), (0.4, -0.35), (0.4, -0.9), (1.6, 0.0), (0.4, 0.9), (0.4, 0.35), (-1.6, 0.35)]
    root = bpy.data.objects.new(name, None)
    env.objects.link(root)
    for nm, m, g in ((name + "_fill", arrow_y, 0.0), (name + "_line", arrow_k, 0.18)):
        q = [(x * (1 + g / 1.6) * scale, y * (1 + g / 0.9) * scale, -0.03 if g else 0.0) for x, y in pts]
        o = W.mesh_obj(nm, q, [list(range(len(q)))], m, env)
        o.parent = root
        o.visible_shadow = False
    return root


arr_back = arrow("arrow_back", 4.0, arrow_r)       # the jam: backwards, next to the band
arr_fwd = arrow("arrow_fwd", 3.4, arrow_w)         # the cars: forwards, further inside
la, ra_, lf, rf, sb, sf = [], [], [], [], [], []
on_frames = [f for f, q in zip(frames, D["arrows"]) if q[2] > 0]
f_on = on_frames[0] if on_frames else N + 10
f_off = on_frames[-1] if on_frames else N + 10
for f, (mid, hs, on) in zip(frames, D["arrows"]):
    if on <= 0:
        mid, hs = (D["arrows"][f_on - 1][0], D["arrows"][f_on - 1][1]) if f < f_on else \
            (D["arrows"][f_off - 1][0], D["arrows"][f_off - 1][1])
    th_b, th_f = mid / R, hs / R
    rb, rfw = R - 9.0, R - 19.0                         # both inside the ring, the jam arrow next to the band
    la.append((rb * math.cos(th_b), rb * math.sin(th_b), 3.0))
    ra_.append((0.0, 0.0, th_b - math.pi / 2))          # arrow +x along the backwards tangent
    lf.append((rfw * math.cos(th_f), rfw * math.sin(th_f), 3.0))
    rf.append((0.0, 0.0, th_f + math.pi / 2))           # arrow +x along the driving direction
    k = 0.0
    if f_on <= f <= f_off:
        k = min(1.0, (f - f_on) / 6.0) * (1.12 if f - f_on in (4, 5) else 1.0)
        k = min(k, max(0.0, (f_off - f) / 5.0))
    sb.append((k, k, k))
stage.bake_motion(arr_back, frames, la, ra_)
stage.bake_motion(arr_fwd, frames, lf, rf)
for o in (arr_back, arr_fwd):
    for f, s3 in zip(frames, sb):
        o.scale = s3
        o.keyframe_insert("scale", frame=f)

# ------------------------------------------------------------------ cameras
cams = {}
for name, cd in D["cams"].items():
    co = stage.camera(name, cd["lens"])
    locs, rots = [], []
    for p, q, u_ in zip(cd["pos"], cd["tgt"], cd["up"]):
        locs.append(tuple(p))
        rots.append(tuple(stage.look_rot(Vector(p), Vector(q), Vector(u_) if u_ else None)))
    for k in range(1, len(rots)):
        r_ = list(rots[k])
        for j in range(3):
            while r_[j] - rots[k - 1][j] > math.pi:
                r_[j] -= 2 * math.pi
            while r_[j] - rots[k - 1][j] < -math.pi:
                r_[j] += 2 * math.pi
        rots[k] = tuple(r_)
    stage.bake_motion(co, cd["frames"], locs, rots)
    sc.timeline_markers.new(name, frame=cd["f0"]).camera = co
    cams[name] = co
sc.camera = cams[D["shot"][0]]

# ------------------------------------------------------------------ look and render
stage.sky(None, Vector((0.45, 0.85, 0.0)).normalized(), ASSETS, sun_elev_deg=32.0)
stage.hazify_all(dist=2400.0, skip=("jam_band", "trackc_arrow_red", "trackc_arrow_white", "trackc_arrow_line") +
                 tuple(m.name for m in chip_mats))
stage.render_setup(SAMPLES, RES, int(round(RES * 16 / 9)))
os.makedirs(OUT, exist_ok=True)
todo = STILLS or list(range(FR[0], FR[1] + 1) if FR else range(1, N + 1))
BLUR = sc.render.use_motion_blur and not NOBLUR      # as stage.render_setup / kit/perf.py chose for this profile
for f in todo:
    sc.frame_set(f)
    cam = cams[D["shot"][f - 1]]
    if sc.camera != cam:              # a camera assignment rebuilds the depsgraph relations: only at cuts
        sc.camera = cam
    blur = BLUR and f not in cuts     # no blur on the first and last frame of a shot (cars jump between windows)
    if sc.render.use_motion_blur != blur:
        sc.render.use_motion_blur = blur
    sc.render.filepath = os.path.join(OUT, f"f_{f:04d}.png")
    bpy.ops.render.render(write_still=True)
    print("Saved", sc.render.filepath, flush=True)
print("RENDER_DONE", FR)
